import { createHash } from 'node:crypto';
import { readFileSync, readdirSync, writeFileSync } from 'node:fs';
import { resolve } from 'node:path';

const pkg='infrastructure/upgrades/launch-readiness-v2';
const read=(path)=>readFileSync(path,'utf8');
const write=(path,value)=>writeFileSync(path,value);
function replaceOne(path,before,after){const value=read(path);if(!value.includes(before))throw new Error(`Missing finalizer anchor: ${path}`);if(value.indexOf(before)!==value.lastIndexOf(before))throw new Error(`Non-unique finalizer anchor: ${path}`);write(path,value.replace(before,after));}

replaceOne(`${pkg}/release.mjs`,"import { appwriteContext, withAppwrite } from './appwrite-session.mjs';","import { withAppwrite } from './appwrite-session.mjs';");
replaceOne(`${pkg}/release.mjs`,"import { deployGoogle, googleIdentity, rollbackGoogle } from './actions/google.mjs';","import { deployGoogle, rollbackGoogle } from './actions/google.mjs';");
replaceOne(`${pkg}/release.mjs`,"import { acquireLock, assertClean, assertRepository, atomicJson, candidate, canonical, git, hash, manifest, packageRoot, readJson, redact, requireThat, root, safePath, sameSourceCandidate, stateRoot } from './runtime.mjs';","import { acquireLock, assertClean, assertRepository, atomicJson, candidate, canonical, git, hash, manifest, packageRoot, readJson, redact, requireThat, root, run, safePath, sameSourceCandidate, stateRoot } from './runtime.mjs';");
replaceOne(`${pkg}/release.mjs`,"  const platformConfig=readJson(platformPath);const acceptance=assertFreshStaging(platformConfig,context);await toolchain(true);const providers=await productionProviderPreflight(target,resolve(releaseDirectory(),'preflight'));","  const platformConfig=readJson(platformPath);for(const environment of ['development','staging']){const other=platformConfig.environments?.[environment];requireThat(other&&target.appwrite.projectId!==other.appwrite.projectId&&target.google.projectId!==other.google.projectId&&target.cloudflare.workerName!==other.cloudflare.workerName&&target.web.origin!==other.web.origin,`Production provider targets must be isolated from ${environment}`);}const acceptance=assertFreshStaging(platformConfig,context);await toolchain(true);const providers=await productionProviderPreflight(target,resolve(releaseDirectory(),'preflight'));");
replaceOne(`${pkg}/release.mjs`,"const value=JSON.parse(await import('./process.mjs').then(({run})=>run('gcloud',['run','services','describe',name,'--project',target.google.projectId,'--region',target.google.region,'--format=json'],{live:true,sensitive:true})));","const value=JSON.parse(await run('gcloud',['run','services','describe',name,'--project',target.google.projectId,'--region',target.google.region,'--format=json'],{live:true,sensitive:true}));");
replaceOne(`${pkg}/release.mjs`,"requireThat(real(app.projectId)&&real(app.projectName)&&/production/i.test(app.projectName),'Use a dedicated named Production Appwrite project');","requireThat(real(app.projectId)&&/^[A-Za-z0-9][A-Za-z0-9._-]{0,35}$/u.test(app.projectId)&&real(app.projectName)&&/production/i.test(app.projectName),'Use a dedicated named Production Appwrite project');");
replaceOne(`${pkg}/release.mjs`,"requireThat(real(google?.projectId)&&google.environment==='production'&&google.region==='australia-southeast1','Use a dedicated labelled Production Google Cloud project');","requireThat(real(google?.projectId)&&/^[a-z][a-z0-9-]{4,61}[a-z0-9]$/u.test(google.projectId)&&google.environment==='production'&&google.region==='australia-southeast1','Use a dedicated labelled Production Google Cloud project');");
replaceOne(`${pkg}/release.mjs`,"requireThat(real(cloudflare?.accountId)&&/^[a-f0-9]{32}$/iu.test(cloudflare.accountId)&&real(cloudflare.workerName)&&/(?:prod|production)/u.test(cloudflare.workerName),'Use a dedicated Production Cloudflare account/worker binding');","requireThat(real(cloudflare?.accountId)&&/^[a-f0-9]{32}$/iu.test(cloudflare.accountId)&&real(cloudflare.workerName)&&/^[a-z0-9_-]+$/u.test(cloudflare.workerName)&&/(?:prod|production)/u.test(cloudflare.workerName),'Use a dedicated Production Cloudflare account/worker binding');");

const packagePath='package.json';const packageJson=JSON.parse(read(packagePath));packageJson.scripts['launch:release']='node infrastructure/upgrades/launch-readiness-v2/release.mjs';packageJson.scripts['launch:test']='node --test infrastructure/upgrades/launch-readiness-v2/tests/*.test.mjs';write(packagePath,`${JSON.stringify(packageJson,null,2)}\n`);

const manifestPath=`${pkg}/manifest.json`;const manifest=JSON.parse(read(manifestPath));manifest.version='2.5.0';manifest.productionReleaseController=true;manifest.cloudflareVersionPromotion=true;write(manifestPath,`${JSON.stringify(manifest,null,2)}\n`);

const readmePath=`${pkg}/README.md`;const readme=read(readmePath);if(!readme.includes('## V2.5 controlled Production release'))write(readmePath,readme+`\n\n## V2.5 controlled Production release\n\nV2.5 adds a separate \`launch:release\` controller while keeping every existing \`launch:* --env production\` path locked. Production release configuration lives privately under Git state and is initialized from \`release.example.json\`. The controller requires the exact approved main commit, fresh Development and Staging acceptance including rehearsal, provider isolation, an active bounded release window, named support ownership, write-freeze/final-delta approvals, immutable Secret Manager references and a fresh encrypted Production backup/restore probe.\n\nProduction stages are deliberately singular: \`terraform -> credentials -> backup -> schema -> data -> files -> google -> cloudflare -> shopify -> verify\`. There is no Production \`all\` stage. Each stage requires \`RELEASE:<stage>:<production-appwrite-id>:<commit>\`. Google and Cloudflare traffic rollback are separately exposed with exact rollback confirmations; Appwrite data rollback remains a separately reviewed recovery decision.\n\nCloudflare deployment now uses Worker Versions for both non-production and Production. Existing deployments upload the candidate, place it at 0%, smoke the exact version using \`Cloudflare-Workers-Version-Overrides\`, verify version metadata/commit/backend/portal shells/security headers/anonymous denial, and only then promote it to 100%. Development/Staging may bootstrap an empty isolated Worker; Production requires an existing settled deployment so rollback is available before promotion.\n\nThe Production Shopify stage uses the approved \`proinspect-2.myshopify.com\` store/API version, additively reconciles the five required ProInspect order/refund webhook topics to the Production Cloudflare edge, and never deletes legacy subscriptions automatically. Google Calendar remains server-side and the Production runtime validation pins its OAuth callback to the Production Cloudflare edge while Terraform manages the Calendar API.\n\nA successful final stage returns \`PRODUCTION_PROMOTED_AWAITING_OBSERVATION\`. It does not retire legacy Strata/D1/R2/Firebase/Firestore sources.\n`);

const integrity={algorithm:'sha256',files:{}};function files(prefix=''){return readdirSync(resolve(pkg,prefix),{withFileTypes:true}).flatMap((entry)=>{const name=prefix?`${prefix}/${entry.name}`:entry.name;return entry.isDirectory()?files(name):[name];}).sort();}
for(const name of files().filter((name)=>name!=='integrity.json'))integrity.files[name]=createHash('sha256').update(readFileSync(resolve(pkg,name))).digest('hex');write(`${pkg}/integrity.json`,`${JSON.stringify(integrity,null,2)}\n`);
console.log(`Finalized launch-readiness ${manifest.version} with ${Object.keys(integrity.files).length} integrity-bound package files.`);
